"use client"

import { cn } from "cn"
import * as React from "react"

import { Button } from "@/components/ui/button"
import { CloseGlyph } from "@/components/ui/pixel-glyphs"
import { type Point, useWindowDrag } from "@/hooks/use-window-drag"

type WindowProps = Omit<React.ComponentProps<"section">, "title"> & {
  title: string
  defaultPosition?: Point
  isActive?: boolean
  statusBar?: React.ReactNode
  onClose?: () => void
  onActivate?: () => void
}

const ORIGIN: Point = { x: 0, y: 0 }

function stopPointerPropagation(event: React.PointerEvent) {
  event.stopPropagation()
}

function Window({
  title,
  defaultPosition,
  isActive = true,
  statusBar,
  onClose,
  onActivate,
  className,
  style,
  children,
  ...props
}: WindowProps) {
  const isDraggable = defaultPosition !== undefined
  const { position, isDragging, startDrag } = useWindowDrag(defaultPosition ?? ORIGIN)

  return (
    <section
      aria-label={title}
      data-slot="window"
      data-active={isActive}
      data-dragging={isDragging}
      className={cn(
        "flex flex-col pixel-border border-border bg-card text-card-foreground dither-shadow bevel-frame dark:bg-(--ink-1)",
        isDraggable ? "absolute" : "relative",
        className
      )}
      style={isDraggable ? { left: position.x, top: position.y, ...style } : style}
      onPointerDownCapture={onActivate}
      {...props}
    >
      <header
        data-slot="window-titlebar"
        onPointerDown={isDraggable ? startDrag : undefined}
        className={cn(
          "flex h-8 shrink-0 items-center gap-3 border-b-(length:--pixel) border-border pr-1 pl-3 font-pixel text-[16px] leading-none uppercase select-none",
          isActive
            ? "bg-titlebar text-titlebar-foreground"
            : "bg-card text-card-foreground",
          isDraggable && "cursor-grab touch-none",
          isDragging && "cursor-grabbing"
        )}
      >
        <h2 className="truncate">{title}</h2>
        <span aria-hidden="true" className="h-4 min-w-6 flex-1 stripes" />
        {onClose && (
          <Button
            variant="ghost"
            size="icon-xs"
            aria-label={`Close ${title}`}
            className="text-current"
            onPointerDown={stopPointerPropagation}
            onClick={onClose}
          >
            <CloseGlyph />
          </Button>
        )}
      </header>
      <div data-slot="window-body" className="min-h-0 flex-1">
        {children}
      </div>
      {statusBar && (
        <footer
          data-slot="window-statusbar"
          className="flex h-7 shrink-0 items-center gap-2 border-t-(length:--pixel) border-border px-2 text-lg leading-none"
        >
          {statusBar}
        </footer>
      )}
    </section>
  )
}

export { Window, type WindowProps }

"use client"

import {
  type PointerEvent as ReactPointerEvent,
  useCallback,
  useEffect,
  useRef,
  useState,
} from "react"

export type Point = {
  x: number
  y: number
}

export type WindowDrag = {
  position: Point
  isDragging: boolean
  startDrag: (event: ReactPointerEvent<HTMLElement>) => void
}

const DEFAULT_PIXEL = 2

function readPixel(): number {
  const raw = getComputedStyle(document.documentElement).getPropertyValue("--pixel")
  const pixel = Number.parseFloat(raw)
  return Number.isFinite(pixel) && pixel > 0 ? pixel : DEFAULT_PIXEL
}

function snapToPixel(value: number, pixel: number): number {
  return Math.round(value / pixel) * pixel
}

export function useWindowDrag(initialPosition: Point): WindowDrag {
  const [position, setPosition] = useState(initialPosition)
  const [isDragging, setIsDragging] = useState(false)
  const positionRef = useRef(initialPosition)
  const stopRef = useRef<(() => void) | null>(null)

  useEffect(() => () => stopRef.current?.(), [])

  const startDrag = useCallback((event: ReactPointerEvent<HTMLElement>) => {
    if (event.button !== 0) {
      return
    }
    event.preventDefault()
    stopRef.current?.()
    const pixel = readPixel()
    const grab = {
      x: event.clientX - positionRef.current.x,
      y: event.clientY - positionRef.current.y,
    }

    function trackPointer(moveEvent: PointerEvent) {
      const next = {
        x: snapToPixel(moveEvent.clientX - grab.x, pixel),
        y: snapToPixel(moveEvent.clientY - grab.y, pixel),
      }
      positionRef.current = next
      setPosition(next)
    }

    function stop() {
      window.removeEventListener("pointermove", trackPointer)
      window.removeEventListener("pointerup", drop)
      window.removeEventListener("pointercancel", drop)
      stopRef.current = null
    }

    function drop() {
      stop()
      setIsDragging(false)
    }

    window.addEventListener("pointermove", trackPointer)
    window.addEventListener("pointerup", drop)
    window.addEventListener("pointercancel", drop)
    stopRef.current = stop
    setIsDragging(true)
  }, [])

  return { position, isDragging, startDrag }
}
